// Zkontroluje součty, zaokrouhlení, měnu a duplicitu. Rozhodne, co smí do tabulky.
const f = $('Vytěžení faktury').first().json.output ?? {};

// Čísla z faktur chodí v různých formátech: 1 240,00 i 1,240.00.
const cislo = (v) => {
  const t = String(v ?? '').replace(/\s/g, '').replace(/,(\d{2})$/, '.$1').replace(/,/g, '');
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
};

const zaklad = cislo(f.zaklad);
const dph = cislo(f.dph);
const celkem = cislo(f.celkem);
const vs = String(f.variabilniSymbol ?? '').replace(/\D/g, '');
const mena = String(f.mena ?? 'CZK').toUpperCase();
const spolehlivost = cislo(f.spolehlivost) ?? 0;

// Variabilní symboly, které už v tabulce jsou.
const zapsaneVS = $input.all()
  .map((i) => String(i.json.VS ?? '').replace(/\D/g, ''))
  .filter(Boolean);

const duvody = [];

if (spolehlivost < 0.8) duvody.push('nizka spolehlivost vyteni: ' + spolehlivost);
if (!vs) duvody.push('chybi variabilni symbol');
if (vs && zapsaneVS.includes(vs)) duvody.push('podezreni na duplicitu, VS ' + vs + ' uz v tabulce je');
if (mena !== 'CZK') duvody.push('cizi mena ' + mena + ', prepocet patri clovku');
if (!f.datumSplatnosti) duvody.push('chybi datum splatnosti');

if (zaklad === null || dph === null || celkem === null) {
  duvody.push('nepodarilo se precist castky');
} else {
  // Haléřový rozdíl do 1 Kč je u českých faktur normální: DPH se počítá
  // po položkách a celková částka se zaokrouhluje na korunu.
  const rozdil = Math.round((zaklad + dph - celkem) * 100) / 100;
  if (Math.abs(rozdil) > 1) {
    duvody.push('zaklad + DPH se nerovna celkem, rozdil ' + rozdil + ' Kc');
  }
}

return [{
  json: {
    dodavatel: String(f.dodavatel ?? '').trim(),
    ico: String(f.ico ?? '').replace(/\D/g, ''),
    dic: String(f.dic ?? '').trim(),
    vs,
    zaklad: zaklad ?? 0,
    dph: dph ?? 0,
    celkem: celkem ?? 0,
    mena,
    datumVystaveni: f.datumVystaveni ?? '',
    datumSplatnosti: f.datumSplatnosti ?? '',
    spolehlivost,
    muzeDoTabulky: duvody.length === 0,
    duvodKontroly: duvody.join('; ')
  }
}];

